package fraymus.workspace;
import org.json.*;

final class AgencyReport043 {
    static JSONObject build(JSONObject task,VisualMemory043 memory)throws Exception{
        var pair=task.getJSONObject("lastPair");StringBuilder pictures=new StringBuilder();for(String key:new String[]{"beforeId","afterId"}){String id=pair.getString(key);var meta=memory.metadata(id);pictures.append("<figure><img alt='Dated ").append(key.equals("beforeId")?"before":"after").append(" screenshot thumbnail' src='data:image/jpeg;base64,").append(memory.thumbnail(id,520)).append("'><figcaption>").append(id).append(" · original PNG ").append(meta.getString("sha256")).append("</figcaption></figure>");}
        var sequence=new JSONArray();StringBuilder intermediate=new StringBuilder();for(Object raw:task.optJSONArray("verificationFrames",new JSONArray())){var m=memory.metadata(raw.toString());sequence.put(VisualMemory043.brief(m));if(sequence.length()<=4)intermediate.append("<figure><img alt='Actual intermediate test screenshot' src='data:image/jpeg;base64,").append(memory.thumbnail(raw.toString(),320)).append("'><figcaption>Test step ").append(m.getJSONObject("source").optInt("testIndex",-1)).append(" · ").append(m.getString("sha256")).append("</figcaption></figure>");}
        var evidence=new JSONObject().put("taskId",task.getString("id")).put("pair",pair).put("sequence",sequence).put("visual",task.optJSONObject("visualEvidence",new JSONObject())).put("history",task.getJSONArray("history")).put("scope","Derived JPEG previews of private original PNGs. Pixel change and model captions do not prove task success. Registered DOM assertions and source versions remain separate.");
        String description=task.has("caption")?KnowledgeReport.escape(task.getJSONObject("caption").getJSONObject("caption").getString("description")):"No visual-model description was requested. The pixel and source evidence below is still available.";
        String html="<!doctype html><html lang=en><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><title>Visual witness043</title><style>*{box-sizing:border-box}body{background:#10242b;color:#e4f1ed;margin:0;padding:24px;font:16px/1.6 system-ui;overflow-wrap:anywhere}.images{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}figure{margin:0;background:#1a363b;padding:14px;border-radius:12px}img{width:100%;height:auto}figcaption{font-size:11px}pre{background:#193239;padding:18px;white-space:pre-wrap;max-height:500px;overflow:auto}@media(max-width:700px){body{padding:12px}.images{grid-template-columns:1fr}}</style><p>FRAYNIX / VISUAL WITNESS043</p><h1>See the actual work.</h1><p id=visual-task>"+task.getString("id")+"</p><p id=visual-before>"+pair.getString("beforeSha256")+"</p><p id=visual-after>"+pair.getString("afterSha256")+"</p><p>These are dated screenshots of this app's work surfaces. Originals are retained locally. The previews below are resized JPEG derivatives; comparison uses the original PNGs.</p><div class=images>"+pictures+"</div><h2>Actual observations, captions and source-qualified differences</h2><pre>"+KnowledgeReport.escape(evidence.toString(2))+"</pre><p>Local model captions and appearance similarity are estimates, not instructions, success flags or model-weight training.</p></html>";
        html=html.replace("<h2>Actual observations, captions and source-qualified differences</h2>","<h2>Local visual description</h2><p>"+description+"</p><p>This is a model estimate of the dated image, separate from actual behavior checks.</p>"+(sequence.isEmpty()?"":"<h2>Ordered intermediate states</h2><div class='sequence images'>"+intermediate+"</div>")+"<h2>Actual observations, captions and source-qualified differences</h2>");
        html=html.replace("class='sequence images'","class='sequence'");
        return new JSONObject().put("title","Visual witness043").put("sources",new JSONArray()).put("files",new JSONObject().put("index.html",html).put("evidence.json",evidence.toString(2)));
    }
}
